using System;using System.Linq;using UnityEngine;using RoadGunner.Editor;
public static class SurveyGreenwoodPocket{public static string Main(){var q=Quaternion.Euler(0,45,0);var result="";for(float z=54;z<59;z+=.75f)for(float x=39;x<44;x+=.75f){var p=AstraZone01Builder.World(x,z);var cs=Physics.OverlapBox(p+Vector3.up*1.3f,new Vector3(1.15f,.5f,2.85f),q,1,QueryTriggerInteraction.Ignore);if(cs.Length==0)result+="clear "+x+", "+z+"\n";else if(x==41.25f&&z==56.25f)foreach(var c in cs)result+="hit "+c.transform.parent.name+" local="+(Quaternion.Inverse(q)*c.transform.parent.position)+" bounds="+c.bounds+"\n";}return result;}}